"""Owned namespace worker: real TLS HTTP endpoints, persistent clients and conntrack occupancy."""
import hashlib,http.client,json,os,pathlib,ssl,sys,threading
from http.server import BaseHTTPRequestHandler,ThreadingHTTPServer
servers=[];connections={};observed=[]
print(json.dumps(dict(ready=True,pid=os.getpid())),flush=True)
try:
 for line in sys.stdin:
  try:
   data=json.loads(line);op=data['op']
   if op=='serve':
    class Handler(BaseHTTPRequestHandler):
     protocol_version='HTTP/1.1'
     def log_message(self,*args):pass
     def do_GET(self):
      observed.append(dict(port=self.server.server_port,peer=list(self.client_address)));body=self.path.encode();self.send_response(200);self.send_header('Content-Length',str(len(body)));self.end_headers();self.wfile.write(body)
    context=ssl.SSLContext(ssl.PROTOCOL_TLS_SERVER);context.load_cert_chain(data['certificate'],data['key'])
    for port in [18443,18444]:
     server=ThreadingHTTPServer(('198.19.0.1',port),Handler);server.daemon_threads=True;server.socket=context.wrap_socket(server.socket,server_side=True);servers.append(server);threading.Thread(target=server.serve_forever,daemon=True).start()
    result=True
   elif op=='https':
    label=data['label'];connection=connections.get(label)
    if connection is None:connection=http.client.HTTPSConnection(data.get('host','198.19.0.1'),data['port'],context=ssl.create_default_context(cafile=data['certificate']),timeout=1.2)
    try:
     connection.request('GET',data['path']);response=connection.getresponse();body=response.read();connections[label]=connection;result=dict(status=response.status,sha256=hashlib.sha256(body).hexdigest(),local=list(connection.sock.getsockname()))
    except (OSError,TimeoutError,ssl.SSLError,http.client.HTTPException) as error:connection.close();connections.pop(label,None);result=dict(failed=type(error).__name__)
   elif op=='observed':result=list(observed)
   elif op=='tcp_counters':
    lines=pathlib.Path('/proc/net/snmp').read_text().splitlines();parts=[line.split()[1:] for line in lines if line.startswith('Tcp:')];result={k:int(v) for k,v in zip(parts[0],parts[1])}
   elif op=='conntrack':result=dict(count=int(pathlib.Path('/proc/sys/net/netfilter/nf_conntrack_count').read_text()),maximum=int(pathlib.Path('/proc/sys/net/netfilter/nf_conntrack_max').read_text()))
   else:raise ValueError('unsupported worker operation')
   print(json.dumps(dict(ok=True,result=result)),flush=True)
  except Exception as error:print(json.dumps(dict(ok=False,error=type(error).__name__+': '+str(error))),flush=True)
finally:
 for connection in connections.values():connection.close()
 for server in servers:server.shutdown();server.server_close()
